import type {Prisma} from '@/generated/prisma/client'

// Full project detail payload for the detail view.
export type ProjectDetailData = Prisma.ProjectGetPayload<{
  include: {
    Company: true
    ProjectType: true
    Employee: true
    Project: true
    ProjectContact: {
      include: {
        Contact: true
        Employee_ProjectContact_createdByToEmployee: true
      }
    }
    WorkOrder: {
      include: {
        Employee: true
      }
    }
    ProjectBOM: true
    MaterialSerialTrack: {
      include: {
        Company: true
        Employee: true
      }
    }
    other_Project: {
      include: {
        Company: true
        ProjectType: true
      }
    }
    Target: {
      include: {
        VisibilityForRole: {
          include: {
            RoleLevel: {
              include: {
                Role: true
                SubRole: true
              }
            }
          }
        }
      }
    }
  }
}>

import type {Prisma} from '@/generated/prisma/client'

// Full project detail payload for the detail view.
export type ProjectDetailData = Prisma.ProjectGetPayload<{
  include: {
    Company: true
    ProjectType: true
    Employee: true
    Project: true
    ProjectContact: {
      include: {
        Contact: true
        // Include creator metadata for contact link rows.
        Employee_ProjectContact_createdByToEmployee: true
      }
    }
    WorkOrder: {
      include: {
        // Include the creator for list display.
        Employee: true
      }
    }
    ProjectBOM: true
    MaterialSerialTrack: {
      include: {
        Company: true
        Employee: true
      }
    }
    other_Project: {
      include: {
        Company: true
        ProjectType: true
      }
    }
    Target: {
      include: {
        // Include role visibility for the Visibility tab.
        VisibilityForRole: {
          include: {
            RoleLevel: {
              include: {
                Role: true
                SubRole: true
              }
            }
          }
        }
      }
    }
  }
}>
